{"content": "     1|# Hermes Workspace - Path-based setup at /workspace
     2|# Access: hermes.upshalter.com/workspace
     3|
     4|server {
     5|    listen 80;
     6|    server_name hermes.upshalter.com;
     7|    
     8|    # Security headers
     9|    add_header X-Frame-Options "SAMEORIGIN" always;
    10|    add_header X-Content-Type-Options "nosniff" always;
    11|    
    12|    # Path-based setup for /workspace
    13|    location /workspace/ {
    14|        # Remove /workspace prefix before proxying
    15|        rewrite ^/workspace(/.*)$ $1 break;
    16|        
    17|        proxy_pass http://127.0.0.1:3000;
    18|        proxy_http_version 1.1;
    19|        proxy_set_header Upgrade $http_upgrade;
    20|        proxy_set_header Connection 'upgrade';
    21|        proxy_set_header Host $host;
    22|        proxy_set_header X-Real-IP $remote_addr;
    23|        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    24|        proxy_set_header X-Forwarded-Proto $scheme;
    25|        proxy_cache_bypass $http_upgrade;
    26|        
    27|        # WebSocket support
    28|        proxy_read_timeout 86400;
    29|    }
    30|    
    31|    # Redirect root to /workspace
    32|    location = / {
    33|        return 301 /workspace/;
    34|    }
    35|    
    36|    # Health check endpoint
    37|    location /health {
    38|        access_log off;
    39|        return 200 "OK\n";
    40|        add_header Content-Type text/plain;
    41|    }
    42|}
